"""Likelihood-free detection of a second component via the three-term
log-convexity defect and its Lipschitz separation margin."""

from __future__ import annotations

import math
from typing import List, Sequence, Tuple


def defect(x: float, y: float, z: float) -> float:
    """Three-term log-convexity defect D(x, y, z) = x z - y^2.

    Vanishes identically on geometric triples, i.e. on the bin probabilities of
    every truncated exponential, whatever its rate.
    """
    return x * z - y * y


def geom_bin_k(k: int, r: float, j: int) -> float:
    """Bin j of a truncated exponential on k equal cells, r = exp(-b/k)."""
    return r ** j * (1.0 - r) / (1.0 - r ** k)


def mix_bin_k(k: int, rho: float, r: float, j: int) -> float:
    """Bin j of the flat-bulk-plus-spike profile on k equal cells."""
    return (1.0 - rho) / k + rho * geom_bin_k(k, r, j)


def defect_profile(probs: Sequence[float]) -> List[float]:
    """All consecutive three-term defects of an observed bin-probability vector."""
    return [defect(probs[j], probs[j + 1], probs[j + 2])
            for j in range(len(probs) - 2)]


def separation_margin(k: int, rho: float) -> float:
    """Guaranteed sup-norm distance from the mixture to EVERY single law,
    valid for every steepness with exp(-b/k) <= 1/2."""
    return rho * (1.0 - rho) / (32.0 * k)


def implied_weight_lower_bound(k: int, observed_defect: float) -> float:
    """Invert D >= rho(1-rho)/(8k) for the smaller root of rho(1-rho)."""
    target = 8.0 * k * observed_defect          # <= rho(1 - rho)
    if target >= 0.25:
        return 0.5
    if target <= 0.0:
        return 0.0
    return 0.5 * (1.0 - math.sqrt(1.0 - 4.0 * target))


def detect_second_component(counts: Sequence[int], k: int,
                            z_threshold: float = 3.0) -> Tuple[bool, float, float]:
    """Test for a second component using the leading defect only.

    Returns (reject_single_law, defect_value, z_statistic).

    The defect of the observed frequency vector is compared with its
    delta-method standard error under multinomial sampling.  Because the defect
    is identically zero for every single truncated exponential, no fitting of
    the null family is required: rejection is a distance statement, not a
    likelihood-ratio statement.
    """
    n = sum(counts)
    p = [c / n for c in counts]
    d = defect(p[0], p[1], p[2])
    # delta-method variance of x z - y^2 under a multinomial with cell probs p
    grad = (p[2], -2.0 * p[1], p[0])
    cells = (p[0], p[1], p[2])
    var = sum(g * g * q * (1.0 - q) for g, q in zip(grad, cells))
    for a in range(3):
        for b in range(3):
            if a != b:
                var -= grad[a] * grad[b] * cells[a] * cells[b]
    se = math.sqrt(max(var, 0.0) / n)
    z = d / se if se > 0 else 0.0
    return (z > z_threshold), d, z

"""Construction of the identified set for a censored steepness parameter:
a one-sided interval [b_lower, infinity) obtained by tolerance inversion."""

from __future__ import annotations

import math
from typing import Optional, Tuple


def trunc_exp_cdf(b: float, t: float) -> float:
    """Mass in [0, t] of an exponential of rate b conditioned to [0, 1]."""
    return (1.0 - math.exp(-b * t)) / (1.0 - math.exp(-b))


def edge_prob(rho: float, t: float, b: float) -> float:
    """Edge-bin probability of the flat-bulk-plus-spike profile."""
    return (1.0 - rho) * t + rho * trunc_exp_cdf(b, t)


def edge_prob_limit(rho: float, t: float) -> float:
    """Ceiling P_inf = (1-rho) t + rho, attained only as b -> infinity."""
    return (1.0 - rho) * t + rho


def ray_threshold(rho: float, t: float, eps: float) -> float:
    """Smallest B0 >= 1 with 2 rho exp(-B0 t) <= eps.

    Every steepness above B0 is compatible with an observation lying within eps
    of the ceiling, so the identified set contains the ray [B0, infinity).
    """
    if 2.0 * rho <= eps:
        return 1.0
    return max(1.0, math.log(2.0 * rho / eps) / t)


def lower_endpoint(rho: float, t: float, v: float, eps: float) -> float:
    """Smallest steepness compatible with observation v at tolerance eps.

    Solves edge_prob(rho, t, b) = v - eps by bisection, exploiting strict
    monotonicity of b -> edge_prob.  Any b below this value is excluded.
    """
    target = v - eps
    if target <= (1.0 - rho) * t:
        return 0.0                       # nothing is excluded from below
    lo, hi = 1e-9, 1.0
    while edge_prob(rho, t, hi) < target:
        hi *= 2.0
        if hi > 1e12:
            return math.inf              # even b = infinity undershoots
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if edge_prob(rho, t, mid) < target:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def upper_endpoint(rho: float, t: float, v: float,
                   eps: float) -> Optional[float]:
    """Largest compatible steepness, or None when the identified set is a ray.

    A finite upper endpoint exists only if the ceiling itself is incompatible,
    i.e. edge_prob_limit(rho, t) > v + eps.
    """
    P = edge_prob_limit(rho, t)
    if P <= v + eps:
        return None                      # ray: no finite upper limit
    target = v + eps
    lo, hi = 1e-9, 1.0
    while edge_prob(rho, t, hi) < target:
        hi *= 2.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if edge_prob(rho, t, mid) < target:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def identified_set(rho: float, t: float, v: float,
                   eps: float) -> Tuple[float, Optional[float], bool]:
    """Return (lower endpoint, upper endpoint or None, is_ray)."""
    lo = lower_endpoint(rho, t, v, eps)
    hi = upper_endpoint(rho, t, v, eps)
    return lo, hi, hi is None


def report(rho: float, t: float, v: float, eps: float) -> str:
    """Format the corrected, censoring-aware verdict."""
    lo, hi, is_ray = identified_set(rho, t, v, eps)
    if is_ray:
        return (f"steepness >= {lo:.2f}  (LOWER BOUND ONLY; the identified set "
                f"contains the ray [{ray_threshold(rho, t, eps):.2f}, inf) and "
                f"has no finite upper limit at tolerance {eps:g})")
    return f"steepness in [{lo:.2f}, {hi:.2f}] at tolerance {eps:g}"
